trait Ord[T] { def compare(x: T, y: T): Int }
object Ord {
  implicit val frameOrd: Ord[Frame] =
    new Ord[Frame] { def compare(x: Frame, y: Frame): Int = x.crc.compare(y.crc) }
  implicit class OrdOps[T](private val x: T) extends AnyVal {
    def <(y: T)(implicit o: Ord[T]): Boolean = o.compare(x, y) < 0
  }
}
def maxOf[T](xs: List[T])(implicit o: Ord[T]): T =
  xs.reduce((a, b) => if (o.compare(a, b) >= 0) a else b)

